'use client'

import * as React from 'react'
import { HeatShade } from '@/components/shader/heat-shade'

export interface HeatShadeDemoProps {
  base?: string
  hot?: string
  speed?: number
}

export default function Demo({ base = '#2a7bba', hot = '#43c8ff', speed = 1 }: HeatShadeDemoProps) {
  return (
    <div className="relative size-full min-h-96 overflow-hidden bg-background">
      <HeatShade className="absolute inset-0" variant="field" base={base} hot={hot} speed={speed} />
    </div>
  )
}
